j2:if.script:
function configureInputMap() {
	var d = new GlideModal('sn_ui_interaction_configure_ui_interaction_inputs', true);
	d.setTitle('${JS:gs.getMessage("Configure inputs")}');
	d.setPreference('sysparm_prev_interaction', g_form.getValue("interaction"));
	d.setPreference('sysparm_interaction', g_form.getValue("interaction"));
	d.setPreference('sysparm_interaction_input_map', g_form.getValue("interaction_input_map"));
	d.setPreference('focusTrap', true);
	d.render();
}

function onChange_interaction(element, original, changed, loading) {
	var visibility = 'hidden';
	if (changed.length > 0)
		visibility = 'visible';

	var e = gel('${jvar_name}');
	e.style.visibility = visibility;
}

var h = new GlideEventHandler('onChange_interaction', onChange_interaction, '${ref}');
g_event_handlers.push(h);
